constructor(address[] memory initialOwners) {
for (uint256 i = 0; i < initialOwners.length; i++) {
if (initialOwners[i] == address(0)) {
revert OwnableInvalidOwner(address(0));
}
_owners.push(initialOwners[i]);
}
